            entry_full = os.path.join(dir_full, name)
            try:
                if os.path.isdir(entry_full):
                    queue.append(entry_full)
                elif os.path.isfile(entry_full):
                    rel = os.path.relpath(entry_full, worktree)
                    if rel.startswith('..'):
                        continue
                    rel = rel.replace(os.sep, '/')
                    extra_files.add(rel)
