    row_max_cols: list[int] = []
    for row in rows:
        max_col = row.commit_column
        for edge in row.edges_to_parent:
            if edge.from_column > max_col:
                max_col = edge.from_column
            if edge.to_column > max_col:
                max_col = edge.to_column
        row_max_cols.append(max_col)

