    widget: QtWidgets.QWidget,
    text: str | None,
    tip: str | None,
    func: Callable,
    connect: Any,
    *shortcuts: Any,
) -> QtGui.QAction:
    action = QtWidgets.QAction(text, widget)
    if hasattr(action, 'setIconVisibleInMenu'):
        action.setIconVisibleInMenu(True)
    if tip:
        action.setStatusTip(tip)
    connect(action, func)
    if shortcuts:
        action.setShortcuts(shortcuts)
